def mv(x, jv, ls, ld):
    """A x for the COO operator with values jv, sources ls, targets ld.
    Transposition is the SAME function with ls/ld swapped — no new machinery."""
    return np.bincount(ld, weights=jv * x[ls], minlength=NL)


